#!/usr/bin/env bash
# Заголовок PR — на русском (решение владельца 05.11, #1015): он же тема
# коммита в main. Имена из кода — как в коде, метки «(процесс)» и
# «(продукт, <версия>)» не в счёт: без них в заголовке должна быть хоть одна
# кириллическая буква. Заголовок — из TITLE (текст события, только через
# env); выход 1 и строка ::error — если кириллицы нет.
set -euo pipefail
# python3 -I: диапазон кириллицы в grep зависит от локали раннера.
if TITLE=${TITLE-} python3 -I -c '
import os, re, sys
rest = re.sub(r"\((процесс|продукт[^)]*)\)", "", os.environ["TITLE"])
sys.exit(0 if re.search("[\u0400-\u04FF]", rest) else 1)'; then
	exit 0
fi
echo "::error title=Заголовок PR::Заголовок PR — на русском (решение владельца 05.11, #1015): имена из кода — как в коде, метки «(процесс)» и «(продукт, <версия>)» не в счёт."
exit 1
